// 冻结报价与行动条款按完整typed字段比较；热规则不构造JSON来比较业务状态。
#pragma once
#include "military_model.hpp"
#include <tuple>
#include <algorithm>
namespace hanmo::resident {
inline bool same_context(const InteractionContext& a,const InteractionContext& b){return std::tie(a.place_id,a.provider_actor_id,a.role_id,a.kind,a.encounter_id,a.input_error)==std::tie(b.place_id,b.provider_actor_id,b.role_id,b.kind,b.encounter_id,b.input_error);}
inline bool same_context(const std::optional<InteractionContext>& a,const std::optional<InteractionContext>& b){return a.has_value()==b.has_value()&&(!a||same_context(*a,*b));}
inline bool same_retainers(std::vector<RetainerRecord> a,std::vector<RetainerRecord> b){auto less=[](const auto& x,const auto& y){return x.actor_id<y.actor_id;};std::sort(a.begin(),a.end(),less);std::sort(b.begin(),b.end(),less);if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(std::tie(a[i].actor_id,a[i].estate_id,a[i].source_id,a[i].unit_id)!=std::tie(b[i].actor_id,b[i].estate_id,b[i].source_id,b[i].unit_id))return false;return true;}
template<class T> inline bool same_dictionary(std::vector<std::pair<StableId,T>> a,std::vector<std::pair<StableId,T>> b){std::sort(a.begin(),a.end());std::sort(b.begin(),b.end());return a==b;}
inline bool same_terms(const MilitaryTerms& a,const MilitaryTerms& b){if(a.index()!=b.index())return false;if(auto x=std::get_if<OfficeTerms>(&a)){auto& y=std::get<OfficeTerms>(b);return std::tie(x->office_id,x->actor_id,x->organization_id,x->place_id,x->provider_actor_id)==std::tie(y.office_id,y.actor_id,y.organization_id,y.place_id,y.provider_actor_id);}auto& x=std::get<ArmyFormationTerms>(a);auto& y=std::get<ArmyFormationTerms>(b);return std::tie(x.order_id,x.office_id,x.actor_id,x.garrison_id,x.ownership_id,x.place_id,x.organization_id,x.unit_ids,x.member_actor_ids,x.money,x.source_inventory_id,x.source_wallet_id)==std::tie(y.order_id,y.office_id,y.actor_id,y.garrison_id,y.ownership_id,y.place_id,y.organization_id,y.unit_ids,y.member_actor_ids,y.money,y.source_inventory_id,y.source_wallet_id)&&same_dictionary(x.commanders,y.commanders)&&same_dictionary(x.goods,y.goods)&&same_retainers(x.retainers,y.retainers);}
inline bool same_quote(const MilitaryQuote& a,const MilitaryQuote& b){if(a.provisions.has_value()!=b.provisions.has_value())return false;if(a.provisions){auto& x=*a.provisions;auto& y=*b.provisions;if(std::tie(x.food_item_id,x.mouth_count,x.required,x.available,x.full_ticks,x.shortage)!=std::tie(y.food_item_id,y.mouth_count,y.required,y.available,y.full_ticks,y.shortage))return false;}return a.duration==b.duration&&a.participants==b.participants&&a.terms.has_value()==b.terms.has_value()&&(!a.terms||same_terms(*a.terms,*b.terms))&&same_context(a.context,b.context)&&a.template_id==b.template_id&&a.recipient_army_id==b.recipient_army_id&&a.campaign_id==b.campaign_id;}
}
